// Prototype: updates are stored per Slice in this browser, not a server permission system.
const updateStoreKey='slice-updates-v1';
const updateSeeds={
 'manual-chat':[{id:'manual-intro',kind:'更新说明',title:'说明书现在可以直接提问了',body:'试试询问亮度、供电方式和保修期限。每条回答会附上相关原文，方便你继续核对。\n接下来会继续补充常见问题。',date:'2026-09-20T08:00:00Z'}],
 orbit:[{id:'orbit-event',kind:'活动',title:'本周挑战：找到你最喜欢的轨道',body:'调整引力，观察轨道的变化。截下你最喜欢的一刻，和朋友分享你的参数与发现。\n这是活动展示示例，无需报名。',eventDate:'2026-09-27',date:'2026-09-20T07:00:00Z'},{id:'orbit-update',kind:'更新说明',title:'引力实验室 · 探索小贴士',body:'从 1.0× 开始，每次只改变一点引力，更容易观察不同轨道的变化。\n网页提供轻量互动切片，桌面完整版仍为概念演示。',date:'2026-09-19T08:00:00Z'}],
 city:[{id:'city-news',kind:'公告',title:'欢迎来到微型都市',body:'这里会持续记录城市实验的新内容与活动。目前可以在网页体验税率变化，完整版下载尚未开放。',date:'2026-09-20T06:00:00Z'}]
};
function updatesFor(id){const data=readStored(updateStoreKey,{});const list=data&&Array.isArray(data[id])?data[id]:(updateSeeds[id]||[]);return list.filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.body==='string'&&['更新说明','活动','公告'].includes(x.kind))}
function storeUpdates(id,list){try{const data=readStored(updateStoreKey,{});const safe=data&&typeof data==='object'&&!Array.isArray(data)?data:{};localStorage.setItem(updateStoreKey,JSON.stringify({...safe,[id]:list}));return true}catch{toast('保存失败，请检查浏览器存储空间。');return false}}
let updateWorkId=null,updateManaging=false,updateEditing=null,removedUpdate=null;
const updateSection=document.createElement('section');updateSection.id='slice-updates';
function updateDate(d){const date=new Date(d);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('zh-CN')}
function renderSliceUpdates(){const w=works.find(x=>x.id===updateWorkId);if(!w)return;const list=updatesFor(w.id).filter(x=>!x.deleted).sort((a,b)=>new Date(b.date)-new Date(a.date));updateSection.innerHTML=`<div class="updates-heading"><div><span class="eyebrow">FROM THE SLICER</span><h3>动态与更新 <small>${list.length}</small></h3><p>来自 ${escapeHtml(w.author)} 的新消息</p></div><button id="manage-updates">${updateManaging?'完成管理':w.local?'管理更新':'体验发布者管理'}</button></div><p class="updates-local">${w.local?'本机发布者视角':'示例内容 · 可体验发布者视角'} · 修改仅保存在此浏览器，尚未接入账号权限与同步。</p>${updateManaging?'<button id="add-slice-update" class="update-add">＋ 发布一条更新</button>':''}<form id="slice-update-form" hidden><h4 id="update-form-title">发布新动态</h4><div class="update-form-row"><label>类型<select name="kind"><option>更新说明</option><option>活动</option><option>公告</option></select></label><label id="update-event-field" hidden>活动日期（可选）<input type="date" name="eventDate"></label></div><label>标题<input name="title" required maxlength="80" placeholder="这次有什么新鲜事？"></label><label>内容<textarea name="body" required maxlength="4000" rows="5" placeholder="写下版本变化、活动玩法，或想告诉大家的消息…"></textarea></label><p id="update-form-error" role="alert"></p><div class="update-form-actions"><button type="button" id="cancel-slice-update">取消</button><button type="submit" class="dark">保存更新</button></div></form>${removedUpdate&&updateManaging?'<div class="update-undo" role="status">已移除动态 <button id="undo-slice-update">撤销</button></div>':''}<div class="updates-list">${list.map(u=>`<article class="update-card"><div class="update-meta"><span class="update-kind">${escapeHtml(u.kind)}</span><time>${escapeHtml(updateDate(u.date))}</time>${u.edited?'<span>已编辑</span>':''}</div><h4>${escapeHtml(u.title)}</h4>${u.kind==='活动'&&u.eventDate?`<p class="update-event">活动日期 · ${escapeHtml(u.eventDate)}</p>`:''}<p class="update-body">${escapeHtml(u.body)}</p>${updateManaging?`<div class="update-card-actions"><button data-update-edit="${escapeHtml(u.id)}">编辑</button><button data-update-delete="${escapeHtml(u.id)}">删除</button></div>`:''}</article>`).join('')||'<div class="updates-empty">还没有动态。新的更新说明和活动会出现在这里。</div>'}</div>`;
 updateSection.querySelector('#manage-updates').onclick=()=>{updateManaging=!updateManaging;updateEditing=null;renderSliceUpdates()};updateSection.querySelector('#add-slice-update')?.addEventListener('click',()=>editSliceUpdate(null));updateSection.querySelector('#cancel-slice-update').onclick=()=>{updateEditing=null;updateSection.querySelector('form').hidden=true};const form=updateSection.querySelector('form');form.elements.kind.onchange=()=>{updateSection.querySelector('#update-event-field').hidden=form.elements.kind.value!=='活动'};form.onsubmit=e=>{e.preventDefault();if(!updateManaging)return;const title=form.elements.title.value.trim(),body=form.elements.body.value.trim();if(!title||!body){updateSection.querySelector('#update-form-error').textContent='请填写标题和内容。';return}const all=updatesFor(w.id),old=all.find(x=>x.id===updateEditing),entry={id:old?.id||crypto.randomUUID(),kind:form.elements.kind.value,title,body,eventDate:form.elements.kind.value==='活动'?form.elements.eventDate.value:'',date:old?.date||new Date().toISOString(),edited:!!old};const next=old?all.map(x=>x.id===old.id?entry:x):[entry,...all];if(storeUpdates(w.id,next)){updateEditing=null;renderSliceUpdates();toast('更新已保存在本机')}};
 updateSection.querySelectorAll('[data-update-edit]').forEach(b=>b.onclick=()=>editSliceUpdate(b.dataset.updateEdit));updateSection.querySelectorAll('[data-update-delete]').forEach(b=>b.onclick=()=>{const all=updatesFor(w.id),entry=all.find(x=>x.id===b.dataset.updateDelete);if(storeUpdates(w.id,all.map(x=>x.id===entry.id?{...x,deleted:true}:x))){removedUpdate=entry;renderSliceUpdates()}});updateSection.querySelector('#undo-slice-update')?.addEventListener('click',()=>{if(storeUpdates(w.id,updatesFor(w.id).map(x=>x.id===removedUpdate.id?removedUpdate:x))){removedUpdate=null;renderSliceUpdates()}});
}
function editSliceUpdate(id){updateEditing=id;const form=updateSection.querySelector('form'),entry=updatesFor(updateWorkId).find(x=>x.id===id);form.reset();for(const field of ['kind','title','body','eventDate'])if(entry)form.elements[field].value=entry[field]||'';form.hidden=false;form.elements.kind.onchange();updateSection.querySelector('#update-form-title').textContent=id?'编辑动态':'发布新动态';form.elements.title.focus();form.scrollIntoView({behavior:'smooth',block:'nearest'})}
function attachSliceUpdates(id){updateWorkId=id;updateManaging=false;updateEditing=null;removedUpdate=null;document.querySelector('#dialog-stage').after(updateSection);renderSliceUpdates()}
const updatesOpenBefore=openWork;openWork=function(id,remix=false){updatesOpenBefore(id,remix);if(dialog.open&&!remix){attachSliceUpdates(id)}else updateSection.remove()};if(dialog.open&&!remixing)attachSliceUpdates(activeId);
